import { haveSameDawnPlan, parseDawnWorldPlan, type DawnWorldPlan } from '../dawn/contracts/DawnPlans';
import { isPersistentBaseHealthRewards, PERSISTENT_BASE_MAX_HP_BONUS, type PersistentBaseHealthReward } from '../persistentBase/PersistentBaseHealth';
import {
  isPersistentBaseAreaStage,
  type PersistentBaseAreaStage,
} from '../persistentBase/PersistentBaseCore';

/**
 * Kanonische replizierte World-Identitaet.
 *
 * Ein `WorldDescriptor` beschreibt genau eine World-Instanz: welche
 * {@link import('../config/authoring/WorldDefinition').WorldDefinition} sie realisiert und mit
 * welchen Instanzparametern. Er enthaelt ausschliesslich World-Identitaet und
 * World-Konfiguration.
 *
 * Ausdruecklich nicht hier hinein gehoeren Mission Objective, Round Role, Siegbedingungen,
 * Respawn-Budget oder ein `GameMode` als Ersatz fuer die Activity – dafuer existiert der
 * {@link import('./ActivityDescriptor').ActivityDescriptor}.
 */
export interface WorldDescriptor {
  /** Identitaet genau einer World-Instanz. Eine neue World erhaelt immer eine neue Revision. */
  readonly worldRevision: number;
  /**
   * Verweist auf die authored WorldDefinition, z. B. `world:coop-defense:7`. Sie loest im
   * Authoring-Registry auf – ausser bei einer prozeduralen World, die keine authored Grundlage
   * besitzt; dafuer gilt {@link isProceduralWorldDefinitionId}.
   */
  readonly definitionId: string;
  readonly seed: number;
  readonly generatorVersion: number;
  readonly layoutFingerprint: string;
  /** Instanzparameter dieser World; nur echte World-Werte, keine Aktivitaetsdaten. */
  readonly parameters?: WorldParameters;
}

/**
 * Host-autoritative Parameter einer konkreten World-Instanz.
 *
 * Sie unterscheiden zwei Instanzen derselben WorldDefinition. Die semantische Area-Stufe ist
 * eine World-Konfiguration und reist deshalb hier statt in einem Activity- oder Round-Vertrag.
 */
export interface WorldParameters {
  /**
   * Traegt diese World-Instanz ihren persistenten Basiskern?
   *
   * Die authored {@link import('../config/authoring/WorldDefinition').WorldDefinition} sagt nur,
   * *wo* der Kern stuende. Ob er tatsaechlich existiert, entscheidet der Host aus dem
   * Entitlement des Spielers - und genau deshalb reist die Antwort hier mit: Zwei Peers mit
   * unterschiedlichem Wert haben nicht dieselbe World gebaut.
   */
  readonly persistentBaseUnlocked?: boolean;
  /**
   * Host-frozen menu entitlements of the Lobby World: which lobby structures stand besides the
   * ones the persistent base brings. Peers read them, so every peer builds the host's Lobby.
   */
  readonly lobbyItemsUnlocked?: boolean;
  readonly lobbyDawnUnlocked?: boolean;
  /** Semantische, fuer diese World-Instanz eingefrorene Area-Stufe der persistenten Basis. */
  readonly persistentBaseAreaStage?: PersistentBaseAreaStage;
  readonly persistentBaseHealthRewards?: readonly PersistentBaseHealthReward[];
  /** Host-frozen extra core HP of this World (Dawn expansion track, D-46); absent = none. */
  readonly persistentBaseHpBonus?: number;
  /**
   * Host-komponierter World-Plan einer Dawn-Runde. Eine Dawn-World besitzt keine authored
   * Registry-Definition; jeder Peer loest sie aus genau diesem Plan auf.
   */
  readonly dawn?: DawnWorldPlan;
}

/**
 * WorldDefinition-ID einer prozedural erzeugten Arena. Sie besitzt bewusst keine authored
 * WorldDefinition: ihre Grundlage ist der Generator, nicht eine Datei.
 */
export const PROCEDURAL_ARENA_WORLD_DEFINITION_ID = 'world:procedural-arena';

/** True, wenn zu dieser World-ID grundsaetzlich keine authored WorldDefinition existiert. */
export function isProceduralWorldDefinitionId(definitionId: string): boolean {
  return definitionId === PROCEDURAL_ARENA_WORLD_DEFINITION_ID;
}

/**
 * Felder, die eine World-Instanz konfigurieren. Sie sind Teil ihrer Identitaet: zwei Peers mit
 * unterschiedlichen Parametern haben nicht dieselbe World gebaut.
 */
export const WORLD_PARAMETER_FIELDS = [
  'persistentBaseUnlocked',
  'lobbyItemsUnlocked',
  'lobbyDawnUnlocked',
  'persistentBaseAreaStage',
  'persistentBaseHealthRewards',
  'persistentBaseHpBonus',
  'dawn',
] as const satisfies readonly (keyof WorldParameters)[];

/** Boolean World-Parameter, an denen authored Inhalt haengen kann (`requiresWorldParameters`). */
export type WorldFlagParameter = 'persistentBaseUnlocked' | 'lobbyItemsUnlocked' | 'lobbyDawnUnlocked';

/**
 * Netzwerkgrenze fuer eingehende World-Identitaeten. Ungueltige Nutzlast wird verworfen statt
 * teilweise uebernommen; die fruehere gemischte Arena-Identitaet ist dafuer keine Quelle mehr.
 */
export function parseWorldDescriptor(raw: unknown): WorldDescriptor | null {
  if (!raw || typeof raw !== 'object') return null;
  const candidate = raw as Partial<WorldDescriptor>;
  if (!isSafePositiveInteger(candidate.worldRevision)) return null;
  if (typeof candidate.definitionId !== 'string' || candidate.definitionId.length === 0) return null;
  if (!isSafeInteger(candidate.seed)) return null;
  if (!isSafeInteger(candidate.generatorVersion)) return null;
  if (typeof candidate.layoutFingerprint !== 'string' || candidate.layoutFingerprint.length === 0) return null;
  const parameters = parseWorldParameters(candidate.parameters);
  if (candidate.parameters?.persistentBaseHealthRewards !== undefined
    && !isPersistentBaseHealthRewards(candidate.parameters.persistentBaseHealthRewards)) return null;
  // Ein unlesbarer Dawn-Plan darf nicht zu einer World ohne Plan werden.
  if (candidate.parameters?.dawn !== undefined && !parameters?.dawn) return null;
  const descriptor: WorldDescriptor = {
    worldRevision: candidate.worldRevision,
    definitionId: candidate.definitionId,
    seed: candidate.seed,
    generatorVersion: candidate.generatorVersion,
    layoutFingerprint: candidate.layoutFingerprint,
  };
  return parameters ? { ...descriptor, parameters } : descriptor;
}

/**
 * True, wenn beide Descriptoren dieselbe World-Instanz meinen. Die Revision allein genuegt
 * nicht: zwei Peers muessen auch dasselbe Layout und dieselbe World-Konfiguration haben.
 */
export function isSameWorldInstance(left: WorldDescriptor, right: WorldDescriptor): boolean {
  return left.worldRevision === right.worldRevision
    && left.definitionId === right.definitionId
    && left.seed === right.seed
    && left.generatorVersion === right.generatorVersion
    && left.layoutFingerprint === right.layoutFingerprint
    && haveSameWorldParameters(left.parameters, right.parameters);
}

/** Feldweiser Vergleich, damit ein neuer World-Parameter nicht still aus der Identitaet faellt. */
export function haveSameWorldParameters(
  left: WorldParameters | undefined,
  right: WorldParameters | undefined,
): boolean {
  return WORLD_PARAMETER_FIELDS.every((field) => {
    if (field === 'dawn') return haveSameDawnPlan(left?.dawn, right?.dawn);
    if (field !== 'persistentBaseHealthRewards') return (left?.[field] ?? null) === (right?.[field] ?? null);
    const a = left?.[field];
    const b = right?.[field];
    if (!a || !b) return a === b;
    return a.length === b.length && a.every((reward) => b.includes(reward));
  });
}

/**
 * True, wenn der effektive Freischaltungsstatus der persistenten Basis wechselt.
 *
 * Der Status wird bewusst als effektiver Boolean verglichen: Ein fehlender Parameter bedeutet
 * fuer die Lobby denselben gesperrten Zustand wie `persistentBaseUnlocked: false`.
 */
export function hasPersistentBaseUnlockStatusChanged(
  left: Pick<WorldDescriptor, 'parameters'> | null | undefined,
  right: Pick<WorldDescriptor, 'parameters'> | null | undefined,
): boolean {
  return (left?.parameters?.persistentBaseUnlocked === true)
    !== (right?.parameters?.persistentBaseUnlocked === true);
}

/** True, wenn sich die Menge der Lobby-Gebaeude einer LobbyWorld-Instanz aendert. */
export function hasLobbyBuildingSetChanged(
  left: Pick<WorldDescriptor, 'parameters'> | null | undefined,
  right: Pick<WorldDescriptor, 'parameters'> | null | undefined,
): boolean {
  return hasPersistentBaseUnlockStatusChanged(left, right)
    || (left?.parameters?.lobbyItemsUnlocked === true) !== (right?.parameters?.lobbyItemsUnlocked === true)
    || (left?.parameters?.lobbyDawnUnlocked === true) !== (right?.parameters?.lobbyDawnUnlocked === true);
}

/** True, wenn sich die fuer die persistente Basis sichtbare World-Konfiguration veraendert. */
export function hasPersistentBaseConfigurationChanged(
  left: Pick<WorldDescriptor, 'parameters'> | null | undefined,
  right: Pick<WorldDescriptor, 'parameters'> | null | undefined,
): boolean {
  return hasPersistentBaseUnlockStatusChanged(left, right)
    || (left?.parameters?.persistentBaseAreaStage ?? null)
      !== (right?.parameters?.persistentBaseAreaStage ?? null)
    || (left?.parameters?.persistentBaseHpBonus ?? 0) !== (right?.parameters?.persistentBaseHpBonus ?? 0)
    || !haveSameWorldParameters(
      { persistentBaseHealthRewards: left?.parameters?.persistentBaseHealthRewards },
      { persistentBaseHealthRewards: right?.parameters?.persistentBaseHealthRewards },
    );
}

/**
 * Jedes Feld wird einzeln geprueft; ein ungueltiger Wert verwirft die ganze Nutzlast, statt
 * still auf einen lokalen Ersatzwert zu fallen. Bleibt kein Feld uebrig, traegt diese World
 * schlicht keine Parameter.
 */
function parseWorldParameters(raw: unknown): WorldParameters | null {
  if (!raw || typeof raw !== 'object') return null;
  const candidate = raw as Partial<WorldParameters>;
  const parameters: {
    persistentBaseUnlocked?: boolean;
    lobbyItemsUnlocked?: boolean;
    lobbyDawnUnlocked?: boolean;
    persistentBaseAreaStage?: PersistentBaseAreaStage;
    persistentBaseHealthRewards?: PersistentBaseHealthReward[];
    persistentBaseHpBonus?: number;
    dawn?: DawnWorldPlan;
  } = {};

  const healthRewards = candidate.persistentBaseHealthRewards;
  if (healthRewards !== undefined) {
    if (!isPersistentBaseHealthRewards(healthRewards)) return null;
    parameters.persistentBaseHealthRewards = [...healthRewards];
  }
  const unlocked = candidate.persistentBaseUnlocked;
  if (unlocked !== undefined) {
    if (typeof unlocked !== 'boolean') return null;
    parameters.persistentBaseUnlocked = unlocked;
  }

  for (const field of ['lobbyItemsUnlocked', 'lobbyDawnUnlocked'] as const) {
    const flag = candidate[field];
    if (flag === undefined) continue;
    if (typeof flag !== 'boolean') return null;
    parameters[field] = flag;
  }

  const hpBonus = candidate.persistentBaseHpBonus;
  if (hpBonus !== undefined) {
    if (!isSafeInteger(hpBonus) || hpBonus < 0 || hpBonus > PERSISTENT_BASE_MAX_HP_BONUS) return null;
    parameters.persistentBaseHpBonus = hpBonus;
  }

  const areaStage = candidate.persistentBaseAreaStage;
  if (areaStage !== undefined) {
    if (!isPersistentBaseAreaStage(areaStage)) return null;
    parameters.persistentBaseAreaStage = areaStage;
  }

  if (candidate.dawn !== undefined) {
    const dawn = parseDawnWorldPlan(candidate.dawn);
    if (!dawn) return null;
    parameters.dawn = dawn;
  }

  return Object.keys(parameters).length > 0 ? parameters : null;
}

function isSafeInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value);
}

function isSafePositiveInteger(value: unknown): value is number {
  return isSafeInteger(value) && value > 0;
}
