import { runtimeImage, runtimeTextureExists, setRuntimeTexture } from '../assets/RuntimeAtlases';
import { BUTTON_CURSOR } from './gameCursor';
import { UiTooltip } from './UiTooltip';
import * as Phaser from 'phaser';
import { activateUi, playUiHover } from './UiAudio';
import { FOREST, skinTextColor, type UiSkin } from './UiSkin';
import { ensureForestPanel } from './forestTextures';
import { COLORS, GAME_HEIGHT, GAME_WIDTH, toCssColor } from '../config';
import { ensureFlatPanelTexture, ensureIconTexture, lerpColor } from './uiTextures';
import { BORDER, RADIUS, SPACE, SURFACE, TEXT, textStyle } from './uiTheme';
import { fitLoadoutIcon, getLoadoutIconTextureKey } from './LoadoutIconLayout';
import { promoteToClarityCamera } from '../scenes/arena/ClarityCameraRegistry';

/** Ein waehlbarer Eintrag im Auswahl-Popup. */
export interface LoadoutPickerEntry {
  readonly key: string;
  readonly displayName: string;
  readonly textureKey: string | null;
  readonly accentColor: number;
  /** Liegt bereits in genau diesem Slot. */
  readonly selected: boolean;
  /** Gesperrt oder bereits in einem anderen Slot derselben Gruppe; nicht waehlbar. */
  readonly disabled: boolean;
  readonly tooltip?: string;
  /** Landscape thumbnail using the same texture lookup as other picker images. */
  readonly preview?: { readonly aspectRatio: number; readonly subtitle?: string };
  readonly onPick: () => void | boolean;
}

/** Benannter Abschnitt im Popup (z.B. "Utility 1" / "Utility 2" beim Inspector). */
export interface LoadoutPickerGroup {
  readonly label: string | null;
  readonly entries: readonly LoadoutPickerEntry[];
  /** One full-width row per entry, following the compact grid. */
  readonly fullWidth?: boolean;
}

export interface LoadoutPickerSafeArea {
  /** Linke bzw. obere Kante im Designraum. */
  readonly left: number;
  readonly top: number;
  /** Rechte bzw. untere Aussenkante im Designraum. */
  readonly right: number;
  readonly bottom: number;
}

export interface LoadoutPickerOptions {
  readonly anchorX: number;
  readonly anchorY: number;
  /** Unterkante des Popups oberhalb des Ausloesers, falls darunter kein Platz ist. */
  readonly aboveAnchorY?: number;
  readonly title: string;
  readonly groups: readonly LoadoutPickerGroup[];
  /** Ueberschreibt die gemeinsame Spaltenobergrenze fuer spezielle Einbettungen. */
  readonly maxColumns?: number;
  /** Explicit grid geometry for compact room settings; loadout defaults are unchanged. */
  readonly columns?: number;
  readonly entryWidth?: number;
  readonly entryHeight?: number;
  readonly centeredLabels?: boolean;
  /** Optionale sichere Overlay-Zone; das Popup bleibt mit seiner ganzen Flaeche darin. */
  readonly safeArea?: LoadoutPickerSafeArea;
  /** Optionale "Slot leeren"-Aktion; nur fuer Slots, die leer bleiben duerfen. */
  readonly clearLabel?: string;
  readonly onClear?: () => void;
}

const PADDING = SPACE.md;
const TITLE_H = 22;
const GROUP_LABEL_H = 18;
const ENTRY_W = 190;
const ENTRY_H = 32;
const ENTRY_GAP = SPACE.xs;
const DEFAULT_MAX_COLUMNS = 3;
const SCREEN_MARGIN = 12;
const ICON_SIZE = 22;

interface RowVisualState {
  readonly fillColor: number;
  readonly fillAlpha: number;
  readonly strokeColor: number;
  readonly strokeWidth: number;
  readonly strokeAlpha: number;
  readonly labelColor?: number;
}

/**
 * Auswahl-Popup fuer Loadout-Slots und Lobby-Einstellungen;
 * die Freischaltungslogik bleibt beim Aufrufer.
 */
export class LoadoutSlotPicker {
  private tooltip: UiTooltip | null = null;
  private container: Phaser.GameObjects.Container | null = null;
  private readonly parentDestroyed = (): void => this.close();
  private readonly escape = (event: KeyboardEvent): void => {
    event.stopImmediatePropagation();
    this.close();
  };

  constructor(
    private readonly scene: Phaser.Scene,
    private readonly parent: Phaser.GameObjects.Container,
    private readonly depth: number,
    private readonly standalone = false,
    private readonly skin: UiSkin = 'default',
  ) {}

  isOpen(): boolean {
    return this.container !== null;
  }

  close(): void {
    this.tooltip?.destroy();
    this.tooltip = null;
    this.parent.off('destroy', this.parentDestroyed);
    this.scene.input.keyboard?.off('keydown-ESC', this.escape);
    this.container?.destroy(true);
    this.container = null;
  }

  open(options: LoadoutPickerOptions): void {
    this.close();

    const groups = options.groups.filter((group) => group.entries.length > 0);
    const totalEntries = groups.reduce((sum, group) => sum + group.entries.length, 0);
    if (totalEntries === 0) return;

    const maxColumns = Math.max(1, Math.floor(options.maxColumns ?? DEFAULT_MAX_COLUMNS));
    const columns = options.columns === undefined
      ? Math.min(maxColumns, Math.max(1, Math.ceil(Math.sqrt(totalEntries))))
      : Math.max(1, Math.floor(options.columns));
    const entryW = options.entryWidth ?? ENTRY_W;
    const entryH = options.entryHeight ?? ENTRY_H;
    const bodyW = columns * entryW + (columns - 1) * ENTRY_GAP;
    const width = bodyW + PADDING * 2;

    let cursorY = PADDING + TITLE_H;
    const rows: Array<() => void> = [];
    const children: Phaser.GameObjects.GameObject[] = [];

    for (const group of groups) {
      if (group.label) {
        const labelY = cursorY;
        rows.push(() => children.push(this.scene.add.text(PADDING, labelY, group.label!, textStyle('section', {
          color: skinTextColor(this.skin, TEXT.muted),
        })).setOrigin(0, 0).setScrollFactor(0)));
        cursorY += GROUP_LABEL_H;
      }
      const groupColumns = group.fullWidth ? 1 : columns;
      const groupEntryW = group.fullWidth ? bodyW : entryW;
      const groupRows = Math.ceil(group.entries.length / groupColumns);
      const groupEntryH = Math.max(entryH, ...group.entries.map(entry =>
        entry.preview ? groupEntryW / entry.preview.aspectRatio : entryH));
      for (let index = 0; index < group.entries.length; index += 1) {
        const entry = group.entries[index];
        const column = index % groupColumns;
        const row = Math.floor(index / groupColumns);
        const x = PADDING + column * (groupEntryW + ENTRY_GAP);
        const y = cursorY + row * (groupEntryH + ENTRY_GAP);
        rows.push(() => this.buildEntry(children, entry, x, y, groupEntryW, groupEntryH, options.centeredLabels ?? false));
      }
      cursorY += groupRows * (groupEntryH + ENTRY_GAP) + 4;
    }

    if (options.clearLabel && options.onClear) {
      const y = cursorY;
      rows.push(() => this.buildClearRow(children, options.clearLabel!, options.onClear!, PADDING, y, bodyW));
      cursorY += ENTRY_H + ENTRY_GAP;
    }

    const height = cursorY - ENTRY_GAP + PADDING;
    const safeArea = options.safeArea ?? {
      left: SCREEN_MARGIN,
      top: SCREEN_MARGIN,
      right: GAME_WIDTH - SCREEN_MARGIN,
      bottom: GAME_HEIGHT - SCREEN_MARGIN,
    };
    const x = Phaser.Math.Clamp(
      options.anchorX - width / 2,
      safeArea.left,
      Math.max(safeArea.left, safeArea.right - width),
    );
    const y = Phaser.Math.Clamp(
      options.anchorY + height > safeArea.bottom && options.aboveAnchorY !== undefined
        ? options.aboveAnchorY - height
        : options.anchorY,
      safeArea.top,
      Math.max(safeArea.top, safeArea.bottom - height),
    );

    // Vollflaechiger Fangschirm: ein Klick daneben schliesst das Popup.
    const backdrop = this.scene.add.rectangle(GAME_WIDTH / 2 - x, GAME_HEIGHT / 2 - y, GAME_WIDTH, GAME_HEIGHT, 0x000000, 0.35)
      .setScrollFactor(0)
      .setInteractive();
    backdrop.on('pointerdown', (_p: Phaser.Input.Pointer, _lx: number, _ly: number, event: Phaser.Types.Input.EventData) => {
      event.stopPropagation();
      this.close();
    });

    const background = this.scene.add.image(0, 0, this.skin === 'forest' ? ensureForestPanel(this.scene, width, height) : ensureFlatPanelTexture(
      this.scene, `_loadout_picker_${width}x${height}`, width, height, SURFACE.modal, BORDER.subtle,
      { radius: RADIUS.lg, fillAlpha: 0.98, strokeAlpha: 0.9 },
    ))
      .setOrigin(0, 0)
      .setScrollFactor(0)
      .setInteractive();
    background.on('pointerdown', (_p: Phaser.Input.Pointer, _lx: number, _ly: number, event: Phaser.Types.Input.EventData) => {
      event.stopPropagation();
    });

    const title = this.scene.add.text(PADDING, PADDING, options.title, textStyle('label', {
      color: skinTextColor(this.skin, TEXT.primary),
    })).setOrigin(0, 0).setScrollFactor(0);

    for (const build of rows) build();

    if (groups.some(group => group.entries.some(entry => entry.tooltip))) {
      this.tooltip = new UiTooltip(this.scene, 320, undefined, undefined, this.skin);
      // UiTooltip positions itself in design coordinates; cancel the popup's offset.
      children.push(this.scene.add.container(-x, -y, [this.tooltip.build()]));
    }

    this.container = this.scene.add.container(x, y, [backdrop, background, title, ...children])
      .setDepth(this.depth)
      .setScrollFactor(0);
    if (this.standalone) {
      // Lobby cards, personal progression and the badger preview have separate roots.
      // A modal must block all of them, rather than inherit one card's lower depth.
      promoteToClarityCamera(this.scene, this.container);
      this.parent.once('destroy', this.parentDestroyed);
    } else {
      this.parent.add(this.container);
    }
    this.scene.input.keyboard?.on('keydown-ESC', this.escape);
  }

  private buildEntry(
    children: Phaser.GameObjects.GameObject[],
    entry: LoadoutPickerEntry,
    x: number,
    y: number,
    width: number,
    height: number,
    centered: boolean,
  ): void {
    const restState: RowVisualState = {
      fillColor: entry.selected ? entry.accentColor : this.skin === 'forest' ? FOREST.sunken : COLORS.GREY_8,
      fillAlpha: entry.selected ? 0.35 : 0.9,
      strokeColor: entry.selected ? entry.accentColor : this.skin === 'forest' ? FOREST.border : COLORS.GREY_5,
      strokeWidth: entry.selected ? 2 : 1,
      strokeAlpha: entry.disabled ? 0.4 : 0.9,
      labelColor: skinTextColor(this.skin, entry.disabled ? COLORS.GREY_4 : COLORS.GREY_1),
    };
    const hoverState: RowVisualState = {
      // Selected rows keep their saturated fill; active, unselected rows only get
      // a restrained accent tint so hover stays visibly below selection.
      fillColor: entry.selected ? entry.accentColor : lerpColor(this.skin === 'forest' ? FOREST.raised : COLORS.GREY_8, entry.accentColor, 0.1),
      fillAlpha: entry.selected ? 0.6 : 0.92,
      strokeColor: entry.accentColor,
      strokeWidth: entry.selected ? 2 : 1,
      strokeAlpha: entry.selected ? 0.9 : 0.78,
      labelColor: this.skin === 'forest' ? FOREST.text : entry.selected ? COLORS.GREY_1 : lerpColor(COLORS.GREY_1, 0xffffff, 0.08),
    };
    const background = this.scene.add.rectangle(x, y, width, height, restState.fillColor, restState.fillAlpha)
      .setOrigin(0, 0)
      .setStrokeStyle(restState.strokeWidth, restState.strokeColor, restState.strokeAlpha)
      .setScrollFactor(0)
      .setAlpha(entry.disabled ? 0.45 : 1);
    children.push(background);

    if (entry.preview && entry.textureKey && runtimeTextureExists(this.scene.textures, entry.textureKey)) {
      // Contain the entire plate. Never crop landscape art to the loadout icon box.
      const image = runtimeImage(this.scene, x + width / 2, y + height / 2, entry.textureKey);
      const scale = Math.min(width / image.width, height / image.height);
      children.push(image.setDisplaySize(image.width * scale, image.height * scale)
        .setScrollFactor(0).setTint(entry.disabled ? 0x62605a : 0xffffff));
    } else if (!entry.preview && entry.textureKey && runtimeTextureExists(this.scene.textures, entry.textureKey)) {
      const textureKey = getLoadoutIconTextureKey(this.scene, entry.textureKey);
      children.push(fitLoadoutIcon(
        runtimeImage(this.scene, x + 6 + ICON_SIZE / 2, y + height / 2, textureKey),
        ICON_SIZE,
        ICON_SIZE,
      )
        .setScrollFactor(0)
        .setAlpha(entry.disabled ? 0.45 : 1));
    }

    const labelX = entry.preview ? 10 : centered ? width / 2 : SPACE.md + (entry.textureKey ? ICON_SIZE : 0);
    const label = this.scene.add.text(x + labelX, y + height / 2, entry.displayName, textStyle(
      entry.selected ? 'labelSm' : 'caption',
      entry.preview ? { color: 0xd9cfb6, wordWrapWidth: width / 3 - 16 }
        : { color: restState.labelColor!, wordWrapWidth: width - (centered ? SPACE.md : labelX + SPACE.sm) },
    )).setOrigin(centered && !entry.preview ? 0.5 : 0, 0.5).setScrollFactor(0);
    children.push(label);
    if (entry.preview) {
      label.setFontSize(15);
      label.setShadow(1, 2, '#1b1a17', 3, true, true);
      if (entry.disabled) children.push(this.scene.add.image(x + width - 18, y + 18,
        ensureIconTexture(this.scene, 'lock', 18, 0xd9cfb6)).setScrollFactor(0));
      if (entry.preview.subtitle) {
        const subtitle = this.scene.add.text(x + 10, y + height / 2 + label.height / 2 + 10,
          entry.preview.subtitle, textStyle('caption', { color: 0xd9cfb6 })).setFontSize(15).setScrollFactor(0);
        // At the compact lobby size only the name fits. Never shrink below 15 design px.
        if (subtitle.width <= width / 3 - 16 && subtitle.y + subtitle.height <= y + height - 10) children.push(subtitle);
        else subtitle.destroy();
      }
    }

    if (entry.tooltip) {
      background.setInteractive();
      background.on('pointerover', (pointer: Phaser.Input.Pointer) => this.tooltip?.showText(entry.displayName, entry.tooltip!, pointer));
      background.on('pointermove', (pointer: Phaser.Input.Pointer) => this.tooltip?.move(pointer));
      background.on('pointerout', () => this.tooltip?.hide());
    }
    if (entry.disabled) return;

    background.setInteractive({ cursor: BUTTON_CURSOR });
    this.attachRowHover(background, restState, hoverState, label);
    background.on('pointerdown', (_p: Phaser.Input.Pointer, _lx: number, _ly: number, event: Phaser.Types.Input.EventData) => {
      event.stopPropagation();
      activateUi(this.scene, entry.onPick);
      this.close();
    });
  }

  private buildClearRow(
    children: Phaser.GameObjects.GameObject[],
    text: string,
    onClear: () => void,
    x: number,
    y: number,
    width: number,
  ): void {
    const background = this.scene.add.rectangle(x, y, width, ENTRY_H, COLORS.GREY_8, 0.9)
      .setOrigin(0, 0)
      .setStrokeStyle(1, COLORS.RED_3, 0.85)
      .setScrollFactor(0)
      .setInteractive({ cursor: BUTTON_CURSOR });
    const label = this.scene.add.text(x + width / 2, y + ENTRY_H / 2, text, textStyle('labelSm', {
      color: COLORS.RED_2,
    })).setOrigin(0.5).setScrollFactor(0);
    this.attachRowHover(background, {
      fillColor: COLORS.GREY_8,
      fillAlpha: 0.9,
      strokeColor: COLORS.RED_3,
      strokeWidth: 1,
      strokeAlpha: 0.85,
    }, {
      fillColor: COLORS.GREY_8,
      fillAlpha: 1,
      strokeColor: COLORS.RED_3,
      strokeWidth: 1,
      strokeAlpha: 0.85,
    });
    background.on('pointerdown', (_p: Phaser.Input.Pointer, _lx: number, _ly: number, event: Phaser.Types.Input.EventData) => {
      event.stopPropagation();
      activateUi(this.scene, onClear);
      this.close();
    });
    children.push(background, label);
  }

  /** Zeilen bleiben layout-stabil; Hover aendert nur die visuellen Zustandswerte. */
  private attachRowHover(
    background: Phaser.GameObjects.Rectangle,
    restState: RowVisualState,
    hoverState: RowVisualState,
    label?: Phaser.GameObjects.Text,
  ): void {
    background.on('pointerover', () => {
      playUiHover(this.scene);
      background
        .setFillStyle(hoverState.fillColor, hoverState.fillAlpha)
        .setStrokeStyle(hoverState.strokeWidth, hoverState.strokeColor, hoverState.strokeAlpha);
      if (label && hoverState.labelColor !== undefined) label.setColor(toCssColor(hoverState.labelColor));
    });
    background.on('pointerout', () => {
      background
        .setFillStyle(restState.fillColor, restState.fillAlpha)
        .setStrokeStyle(restState.strokeWidth, restState.strokeColor, restState.strokeAlpha);
      if (label && restState.labelColor !== undefined) label.setColor(toCssColor(restState.labelColor));
    });
  }
}
